insert into org.limite (circulo, ordem, texto) select circulo, ordem, texto from jsonb_to_recordset($j$[{"circulo": 1, "ordem": 1, "texto": "Os fluxos são descritivos. Para executar falta escolher o motor e ligar cada tarefa a um sistema."}, {"circulo": 1, "ordem": 2, "texto": "Não há tempo, volume nem carga por pessoa: nada disso foi medido, então nada foi estimado."}, {"circulo": 1, "ordem": 3, "texto": "Com os nove círculos fechados (03/10/2026), as trocas com os outros oito foram conferidas dos dois lados pelo nome: 406 trocas, sem problema."}, {"circulo": 1, "ordem": 4, "texto": "As conferências feitas por outros círculos não têm ramo de recusa desenhado: a recusa devolve o trabalho à tarefa anterior."}, {"circulo": 1, "ordem": 5, "texto": "Na ID-02, as consultas entram pela etapa 1. Se o volume crescer, vale separar em jornada própria; hoje não há medida de volume."}, {"circulo": 1, "ordem": 6, "texto": "Na ID-03, a jornada termina no pedido de registro; oposição ou recusa do registro ainda não tem caminho desenhado."}, {"circulo": 1, "ordem": 7, "texto": "As oito jornadas transferidas foram assumidas pelos círculos de destino, já fechados: material de marca por quem usa a marca; integração cultural (GE-08), propósito pessoal (GE-09), rituais e reconhecimento (GE-10) e comunicação interna (GE-11) pela Gestão; comunicação externa (RE-07) e monitoramento da reputação (RE-08) por Relações; comitê de crise (GO-08), auditoria das entregas (GO-06) e relato de impacto (GO-10) pela Governança. Os rascunhos ficam aqui como histórico."}, {"circulo": 1, "ordem": 8, "texto": "Os números descrevem este desenho, não a operação atual."}, {"circulo": 2, "ordem": 1, "texto": "Os fluxos são descritivos. Para executar falta escolher o motor e ligar cada tarefa a um sistema."}, {"circulo": 2, "ordem": 2, "texto": "Não há tempo, volume nem carga por pessoa: nada disso foi medido, então nada foi estimado."}, {"circulo": 2, "ordem": 3, "texto": "As cadências vêm do método de estratégia aprovado em 03/10/2026: ciclo estratégico anual, com revisão no meio do ciclo (ES-01); portfólio semestral (ES-02); alvos anuais, com o ciclo (ES-03); revisão da execução trimestral (ES-06). São escolha de desenho, sem fonte externa: recalibrar com dados depois de dois ciclos."}, {"circulo": 2, "ordem": 4, "texto": "O método de estratégia tem lugar no desenho (ES-01), mas o conteúdo ainda não foi escrito: critérios dos portões, regras de realocação, critério de desvio grave e calendário."}, {"circulo": 2, "ordem": 5, "texto": "As alçadas que separam a decisão da Estratégia da decisão dos sócios ainda não existem; serão definidas no círculo 9, Governança."}, {"circulo": 2, "ordem": 6, "texto": "A raia “Sócios” não distingue os sócios do Ecossistema dos sócios de cada empresa. Quem delibera o quê fica para o círculo 9."}, {"circulo": 2, "ordem": 7, "texto": "Fusão e cisão de empresas não estão desenhadas: a ES-05 cobre criação, aquisição, venda e encerramento."}, {"circulo": 2, "ordem": 8, "texto": "O plano de saída de clientes, contratos e pessoas é pedido à Integração e conferido pela Estratégia; como ele é montado só será desenhado nos círculos 4 a 9."}, {"circulo": 2, "ordem": 9, "texto": "Captar dinheiro de fora ou admitir sócio numa empresa ficam fora do desenho: a ES-05 não tem ramo para essas operações."}, {"circulo": 2, "ordem": 10, "texto": "A ES-06 abre só a revisão de nível mais alto. Se essa revisão termina sem mudança (os sócios mantêm a estratégia ou a alocação), a de nível abaixo não é aberta por ela; volta na revisão seguinte da ES-06."}, {"circulo": 2, "ordem": 11, "texto": "Quando uma mensagem pode tanto retomar uma jornada em espera quanto abrir outra (a alocação que chega à ES-03, a decisão do portão que chega à IN-07), a correlação fica para o motor de execução."}, {"circulo": 2, "ordem": 12, "texto": "Um laço de volta refaz a etapa inteira: o desenho não marca o que já foi feito na passagem anterior."}, {"circulo": 2, "ordem": 13, "texto": "As esperas por outro círculo (plano de saída, fichas dos indicadores, resposta da Inteligência) não têm prazo desenhado."}, {"circulo": 2, "ordem": 14, "texto": "Na venda decidida sem comprador, a busca do comprador não está desenhada: o mandato a descreve, e a oportunidade volta à ES-05 quando houver comprador."}, {"circulo": 2, "ordem": 15, "texto": "A ES-04 registra a incoerência com a identidade na avaliação e não recomenda avançar; a decisão do portão continua sendo de pessoas."}, {"circulo": 2, "ordem": 16, "texto": "As ofertas de uma empresa adquirida não têm caminho desenhado até o catálogo de ofertas."}, {"circulo": 2, "ordem": 17, "texto": "Com os nove círculos fechados (03/10/2026), as trocas com os outros oito foram conferidas dos dois lados pelo nome: 406 trocas, sem problema."}, {"circulo": 2, "ordem": 18, "texto": "As conferências feitas por outros círculos não têm ramo de recusa desenhado: a recusa devolve o trabalho à tarefa anterior."}, {"circulo": 2, "ordem": 19, "texto": "Os números descrevem este desenho, não a operação atual."}, {"circulo": 3, "ordem": 1, "texto": "Os fluxos são descritivos. Para executar falta escolher o motor e ligar cada tarefa a um sistema."}, {"circulo": 3, "ordem": 2, "texto": "Não há tempo, volume nem carga por pessoa: nada disso foi medido, então nada foi estimado."}, {"circulo": 3, "ordem": 3, "texto": "As cadências foram validadas em 03/10/2026 (aba Parâmetros em aberto); o líder ajusta na implantação. O prazo de resposta da IN-02 depende de volume e ficou para o gate G9 (calibração)."}, {"circulo": 3, "ordem": 4, "texto": "O referencial de processos é o APQC PCF 7.4, de agosto de 2024. A versão 8.0, de 27/02/2026, foi conferida só nas 13 categorias."}, {"circulo": 3, "ordem": 5, "texto": "Com os nove círculos fechados (03/10/2026), as trocas com os outros oito foram conferidas dos dois lados pelo nome: 406 trocas, sem problema."}, {"circulo": 3, "ordem": 6, "texto": "Quando uma empresa sai do portfólio, a IN-07 retira as ofertas dela do catálogo e a IN-04 revê os indicadores. O destino dos dados (IN-03) e das bases (IN-05) dessa empresa ainda não está desenhado."}, {"circulo": 3, "ordem": 7, "texto": "O ajuste de oferta em uso não gera aviso à Estratégia: fica registrado no catálogo de ofertas. Tratar a mudança de preço-base como revisão é leitura do desenho, a confirmar."}, {"circulo": 3, "ordem": 8, "texto": "As ofertas de uma empresa adquirida não têm caminho desenhado até o catálogo de ofertas."}, {"circulo": 3, "ordem": 9, "texto": "Quando uma mensagem pode tanto retomar uma jornada em espera quanto abrir outra, a correlação fica para o motor de execução. Um laço de volta refaz a etapa inteira."}, {"circulo": 3, "ordem": 10, "texto": "As esperas por outra jornada ou por outro círculo só têm prazo onde o nome da tarefa o diz."}, {"circulo": 3, "ordem": 11, "texto": "A contestação de indicador de alvo vigente espera a próxima revisão da estratégia (ES-06); não abre revisão própria."}, {"circulo": 3, "ordem": 12, "texto": "O mandato de criação ou de aquisição de empresa chega à Inteligência, mas a IN-07 só age no de venda fechada ou de encerramento."}, {"circulo": 3, "ordem": 13, "texto": "Exceção ao cálculo único: os indicadores de clareza e atualidade dos padrões são calculados pela Identidade (ID-05) e conferidos com a ficha na IN-04."}, {"circulo": 3, "ordem": 14, "texto": "O líder do círculo aparece como dono de dado, de indicador, de tema e de melhoria. A delegação e a carga desse papel ficam para quando as pessoas forem tratadas."}, {"circulo": 3, "ordem": 15, "texto": "Os indicadores do próprio círculo são calculados por ele; a conferência independente fica para a Governança, no círculo 9."}, {"circulo": 3, "ordem": 16, "texto": "A comparação de desempenho com referências (benchmarking) não está desenhada."}, {"circulo": 3, "ordem": 17, "texto": "O prazo de guarda vale para dados (IN-03). O registro de perguntas e respostas e o registro de lições entram no catálogo de dados como qualquer fonte, com ficha, classificação e prazo de guarda; as bases saem pela revisão da base (IN-05)."}, {"circulo": 3, "ordem": 18, "texto": "Cinco jornadas (IN-01, IN-02, IN-03, IN-04 e IN-08) não têm ponto de conferência com a identidade, porque produzem análise e medida para uso interno. Se a regra do círculo 1 vale para toda jornada, falta incluir o ponto nas cinco."}, {"circulo": 3, "ordem": 19, "texto": "As jornadas cross da rodada 2 em que a Inteligência participava (C5, C8, C11 e V7) viraram cadeias de jornadas na consolidação de 03/10/2026 (aba Mapa de jornadas); as entregas da Inteligência a esses círculos estão no cruzamento."}, {"circulo": 3, "ordem": 20, "texto": "As aprovações e conferências sem decisão desenhada não têm ramo de recusa: a recusa devolve o trabalho a quem preparou."}, {"circulo": 3, "ordem": 21, "texto": "O desenho não tem evento de interrupção nem saída condicional. A aposta encerrada fora do portão de lançamento, com desenvolvimento em curso, entra na IN-07 como novo início, e é esse caminho que encerra o trabalho aberto; quando uma saída só existe num ramo, o nome do produto diz qual."}, {"circulo": 3, "ordem": 22, "texto": "Os padrões da Identidade chegam aos agentes por dois caminhos: a carga direta pela Integração (ID-02 e ID-04) e a base de conhecimento (IN-05). Unificar a carga fica para o círculo 6."}, {"circulo": 3, "ordem": 23, "texto": "Se o piloto é pago ou gratuito é decidido pela Inteligência a cada piloto, ouvido Negócios; o desenho não fixa."}, {"circulo": 3, "ordem": 24, "texto": "Os números descrevem este desenho, não a operação atual."}, {"circulo": 4, "ordem": 1, "texto": "Os fluxos são descritivos. Para executar falta escolher o motor e ligar cada tarefa a um sistema."}, {"circulo": 4, "ordem": 2, "texto": "Não há tempo, volume nem carga por pessoa: nada disso foi medido, então nada foi estimado."}, {"circulo": 4, "ordem": 3, "texto": "As cadências foram validadas em 03/10/2026 (aba Parâmetros em aberto); o líder do círculo ajusta na implantação e a calibração com dados é o gate G9."}, {"circulo": 4, "ordem": 4, "texto": "Os rascunhos de critério de oportunidade qualificada, regra de saúde do cliente e critério de crise foram validados em 03/10/2026 (aba Gates de implantação); o texto final é o gate G8, e os números que dependem de dado real ficam nos gates G3 e G9."}, {"circulo": 4, "ordem": 5, "texto": "O referencial de processos é o APQC PCF 7.4, de agosto de 2024. Da ISO 44001 e da ISO 22361 lemos só o resumo; o texto dos Barcelona Principles 3.0 foi lido numa transcrição da MEPRA, porque a página da AMEC só os oferece em anexos."}, {"circulo": 4, "ordem": 6, "texto": "Onde faltava o outro lado, as três propostas aos círculos 2 e 3 foram aceitas e aplicadas às 19:05. Com os nove círculos fechados (03/10/2026), as trocas com os outros oito foram conferidas dos dois lados pelo nome: 406 trocas, sem problema."}, {"circulo": 4, "ordem": 7, "texto": "A tarefa de quem não é do círculo (cliente, parceiro, executivo, outro círculo) está desenhada como participação; o detalhe dela fica no círculo dono."}, {"circulo": 4, "ordem": 8, "texto": "As aprovações e conferências sem decisão desenhada não têm ramo de recusa: a recusa devolve o trabalho a quem preparou."}, {"circulo": 4, "ordem": 9, "texto": "Programa de fidelidade e lobby não estão desenhados: nenhum círculo pediu."}, {"circulo": 4, "ordem": 10, "texto": "As autorizações de uso da marca têm prazo registrado, mas o vencimento não tem vigia desenhada: só a marca retirada de uso revoga as autorizações."}, {"circulo": 4, "ordem": 11, "texto": "Quando Relações indica clientes para conversar e para o piloto (IN-07), usa a base de relacionamento da RE-03; o detalhe dessa tarefa fica no círculo 3."}, {"circulo": 4, "ordem": 12, "texto": "Os números descrevem este desenho, não a operação atual."}, {"circulo": 5, "ordem": 1, "texto": "Os fluxos são descritivos. Para executar falta escolher o motor e ligar cada tarefa a um sistema."}, {"circulo": 5, "ordem": 2, "texto": "Não há tempo, volume nem carga por pessoa: nada disso foi medido, então nada foi estimado."}, {"circulo": 5, "ordem": 3, "texto": "As cadências foram validadas em 03/10/2026 (aba Parâmetros em aberto); o líder do círculo ajusta na implantação e a calibração com dados é o gate G9."}, {"circulo": 5, "ordem": 4, "texto": "A alçada de concessão e as regras gerais dos contratos foram aprovadas em 03/10/2026 (aba Parâmetros em aberto); a estrutura dos modelos e a regra de remuneração (fixo mais variável sobre a receita recebida) foram validadas em 03/10/2026; o texto dos modelos é o gate G8 e os percentuais, o G3."}, {"circulo": 5, "ordem": 5, "texto": "O referencial de processos é o APQC PCF 7.4, de agosto de 2024. Da Lei 14.133 conferimos os arts. 6º (incisos XLV, XLVI, XLVIII e XLIX), 17 e 18; os prazos e o rito de esclarecimento, impugnação, recurso, adesão à ata e contratação direta não foram conferidos e estão como “no prazo do edital”."}, {"circulo": 5, "ordem": 6, "texto": "Com os nove círculos fechados (03/10/2026), as trocas com os outros oito foram conferidas dos dois lados pelo nome: 406 trocas, sem problema."}, {"circulo": 5, "ordem": 7, "texto": "A tarefa de quem não é do círculo (cliente, parceiro, executivo, sócios, outro círculo) está desenhada como participação; o detalhe dela fica no círculo dono."}, {"circulo": 5, "ordem": 8, "texto": "As aprovações e conferências sem decisão desenhada não têm ramo de recusa: a recusa devolve o trabalho a quem preparou."}, {"circulo": 5, "ordem": 9, "texto": "Contratos, aditivos e documentos de licitação seguem o modelo da Governança ou o formato do edital; a conferência com os padrões de identidade fica no material de venda, na proposta e na parte livre da proposta de licitação."}, {"circulo": 5, "ordem": 10, "texto": "As saídas estão listadas por etapa, não por caminho: na NE-05, etapa 4, o contrato só sai quando há contrato ou adesão, e a ata só quando há ata."}, {"circulo": 5, "ordem": 11, "texto": "Se o escopo de uma oferta conjunta mudar na proposta, a divisão acordada entre as empresas precisa ser revista; o desenho não tem esse retorno."}, {"circulo": 5, "ordem": 12, "texto": "Os números descrevem este desenho, não a operação atual."}, {"circulo": 6, "ordem": 1, "texto": "Os fluxos são descritivos. Para executar falta escolher o motor e ligar cada tarefa a um sistema."}, {"circulo": 6, "ordem": 2, "texto": "Não há tempo, volume nem carga por pessoa: nada disso foi medido, então nada foi estimado."}, {"circulo": 6, "ordem": 3, "texto": "As cadências foram validadas em 03/10/2026 (aba Parâmetros em aberto); o líder do círculo ajusta na implantação e a calibração com dados é o gate G9."}, {"circulo": 6, "ordem": 4, "texto": "Os rascunhos de método de projetos, regra de prioridade, critério de liberação de agente e política de segurança foram validados em 03/10/2026 (aba Gates de implantação); o texto final é o gate G8, e os números que dependem de dado real ficam nos gates G3 e G9."}, {"circulo": 6, "ordem": 5, "texto": "Continuidade de TI (APQC 8.3.4) e recuperação de desastre não estão desenhadas como etapa própria."}, {"circulo": 6, "ordem": 6, "texto": "O referencial de processos é o APQC PCF 7.4, de agosto de 2024. Da ISO 21502 e da ISO/IEC 27001 lemos só o resumo."}, {"circulo": 6, "ordem": 7, "texto": "Onde faltava o outro lado, as propostas à NE-01, à IT-04 e à IT-06 foram aprovadas e aplicadas. Com os nove círculos fechados (03/10/2026), as trocas com os outros oito foram conferidas dos dois lados pelo nome: 406 trocas, sem problema."}, {"circulo": 6, "ordem": 8, "texto": "A tarefa de quem não é do círculo (cliente, executivo, líder do círculo dono, outro círculo) está desenhada como participação; o detalhe dela fica no círculo dono."}, {"circulo": 6, "ordem": 9, "texto": "As aprovações e conferências sem decisão desenhada não têm ramo de recusa: a recusa devolve o trabalho a quem preparou."}, {"circulo": 6, "ordem": 10, "texto": "O rateio do custo dos círculos entre as empresas (E3) e o acordo de serviço como jornada entre empresas (E1) ficam para a consolidação das jornadas entre empresas."}, {"circulo": 6, "ordem": 11, "texto": "O método de projetos, a regra de prioridade da carteira e a arquitetura da plataforma, pelos quais o líder corporativo da Integração responde, não têm jornada própria: são mantidos como documentos do círculo e mudam pela IT-08 ou por projeto na IT-01."}, {"circulo": 6, "ordem": 12, "texto": "As saídas estão listadas por etapa, não por caminho: na IT-04, etapa 1, sai o plano de saída de oferta ou o de empresa, conforme o pedido."}, {"circulo": 6, "ordem": 13, "texto": "O agente suspenso volta por novo pedido de correção (IT-06); o lançamento suspenso volta quando o executivo o retoma (IT-03). A Estratégia não é avisada do impedimento de lançamento: a ES-04 não tem essa entrada."}, {"circulo": 6, "ordem": 14, "texto": "A capacidade feita por pessoa ou por assessoria fica “em construção” no catálogo até o projeto aberto na carteira ser entregue; a marcação como “em uso” nesse caso não tem tarefa desenhada."}, {"circulo": 6, "ordem": 15, "texto": "Na saída de empresa, a conclusão do plano é informada à Estratégia dentro da ES-05, etapa 7, pela tarefa da Integração; a “Conclusão do plano de saída da oferta” vale para a ES-04."}, {"circulo": 6, "ordem": 16, "texto": "A amostra de acerto do agente em uso vai à Inteligência, que avalia o método (IN-06, etapa 5); o veredito volta como mudança de método ou de base, não como decisão dentro da IT-06."}, {"circulo": 6, "ordem": 17, "texto": "O projeto em espera que passa a caber volta à priorização por novo registro na IT-01, aberto pelo ciclo de acompanhamento."}, {"circulo": 6, "ordem": 18, "texto": "Os números descrevem este desenho, não a operação atual."}, {"circulo": 7, "ordem": 1, "texto": "Os fluxos são descritivos. Para executar falta escolher o motor e ligar cada tarefa a um sistema."}, {"circulo": 7, "ordem": 2, "texto": "Não há tempo, volume nem carga por pessoa: nada disso foi medido, então nada foi estimado. Os únicos prazos citados são os da lei (CDC e Código Civil), com a fonte."}, {"circulo": 7, "ordem": 3, "texto": "As cadências foram validadas em 03/10/2026 (aba Parâmetros em aberto); o líder do círculo ajusta na implantação e a calibração com dados é o gate G9."}, {"circulo": 7, "ordem": 4, "texto": "Os rascunhos de procedimentos, níveis de serviço e garantia foram validados em 03/10/2026 (aba Gates de implantação); o texto final é o gate G8, e os números que dependem de dado real ficam nos gates G3 e G9."}, {"circulo": 7, "ordem": 5, "texto": "O CDC vale quando o cliente é consumidor. Contrato entre empresas segue o que foi contratado e o Código Civil (arts. 421-A e 441 a 446), lido em transcrição secundária: conferir no texto oficial antes de usar."}, {"circulo": 7, "ordem": 6, "texto": "Uma estratégia de recall prévia (APQC 6.1.7), a manutenção de equipamentos (APQC 4.3.1.5 e 4.3.1.6), o planejamento da distribuição (4.1.5 a 4.1.7), a governança da logística (4.4.1), o registro de produtos (6.3.1) e a estratégia de canais de atendimento (6.1.3) não têm etapa própria."}, {"circulo": 7, "ordem": 7, "texto": "No contrato público, o recebimento provisório e o definitivo seguem o art. 140 da Lei 14.133, lido em transcrição secundária: a OP-02 trata os dois como aceite do cliente."}, {"circulo": 7, "ordem": 8, "texto": "Quando a ação corretiva conclui, quem apontou a lacuna (Identidade, Relações ou Estratégia) vê o efeito pelo painel da Inteligência: os círculos fechados não têm entrada para um aviso direto."}, {"circulo": 7, "ordem": 9, "texto": "A recusa de capacidade no plano chega a Negócios pela confirmação de capacidade feita nas jornadas de Negócios e ao executivo pelo plano publicado; Negócios não recebe o plano como entrada."}, {"circulo": 7, "ordem": 10, "texto": "O referencial de processos é o APQC PCF 7.4, de agosto de 2024. Da ISO 9001 lemos só a página oficial; da ISO 10002, só o resumo."}, {"circulo": 7, "ordem": 11, "texto": "Onde faltava o outro lado, a proposta à IT-04 foi aprovada e aplicada. Com os nove círculos fechados (03/10/2026), as trocas com os outros oito foram conferidas dos dois lados pelo nome: 406 trocas, sem problema."}, {"circulo": 7, "ordem": 12, "texto": "A tarefa de quem não é do círculo (cliente, executivo, Negócios, Gestão, Governança) está desenhada como participação; o detalhe dela fica no círculo dono."}, {"circulo": 7, "ordem": 13, "texto": "As aprovações e conferências sem decisão desenhada não têm ramo de recusa: a recusa devolve o trabalho a quem preparou."}, {"circulo": 7, "ordem": 14, "texto": "As saídas estão listadas por etapa, não por caminho: o pedido à Integração, à Identidade ou à Inteligência só sai quando a decisão pede."}, {"circulo": 7, "ordem": 15, "texto": "Os números descrevem este desenho, não a operação atual."}, {"circulo": 8, "ordem": 1, "texto": "Os fluxos são descritivos. Para executar falta escolher o motor e ligar cada tarefa a um sistema."}, {"circulo": 8, "ordem": 2, "texto": "Não há tempo, volume nem carga por pessoa: nada disso foi medido, então nada foi estimado. O alerta do círculo 1 sobre a carga humana das jornadas transferidas continua sem medida."}, {"circulo": 8, "ordem": 3, "texto": "O ritual de acompanhamento é mensal, pelo método de estratégia aprovado em 03/10/2026. As outras cadências (fechamento, folha, avaliação, rituais de cultura, comunicação interna, rateio e inventário) são decididas pelo líder do círculo, na implantação."}, {"circulo": 8, "ordem": 4, "texto": "Os rascunhos de políticas de cobrança, compras, remuneração e desenvolvimento foram validados em 03/10/2026 (aba Gates de implantação); o texto final é o gate G8, e os números que dependem de dado real ficam nos gates G3 e G9."}, {"circulo": 8, "ordem": 5, "texto": "Da área trabalhista e contábil foram lidos os prazos da folha, das férias e da rescisão (CLT), o depósito do FGTS e a escrituração (Código Civil), parte em transcrição secundária. A regra fiscal não foi citada: os tributos dependem do regime de cada empresa, que não está no modelo (empresas e pessoas ficaram para depois). A apuração segue a lei vigente, com a assessoria."}, {"circulo": 8, "ordem": 6, "texto": "Estratégia e políticas de pessoas (APQC 7.1), relações sindicais e queixas (7.4), benefícios (7.5.2), reembolso de despesas (9.6.2), dívida e aplicações (9.7.4) não têm etapa própria."}, {"circulo": 8, "ordem": 7, "texto": "O fornecedor não é uma parte do vocabulário do modelo: as trocas com ele aparecem como tarefas da Gestão."}, {"circulo": 8, "ordem": 8, "texto": "A cobrança judicial e a recusa de pedido de compra pelo executivo não têm ramo desenhado: a recusa devolve o pedido a quem pediu."}, {"circulo": 8, "ordem": 9, "texto": "O pedido de recurso que mexe na alocação entre empresas fica registrado para a revisão do portfólio: a ES-02 não tem entrada para um pedido direto e lê a execução do orçamento."}, {"circulo": 8, "ordem": 10, "texto": "O referencial de processos é o APQC PCF 7.4, de agosto de 2024."}, {"circulo": 8, "ordem": 11, "texto": "Com os nove círculos fechados (03/10/2026), as trocas com os outros oito foram conferidas dos dois lados pelo nome: 406 trocas, sem problema."}, {"circulo": 8, "ordem": 12, "texto": "A tarefa de quem não é do círculo (líder, pessoa, executivo, outro círculo) está desenhada como participação; o detalhe dela fica no círculo dono."}, {"circulo": 8, "ordem": 13, "texto": "As saídas estão listadas por etapa, não por caminho."}, {"circulo": 8, "ordem": 14, "texto": "Os números descrevem este desenho, não a operação atual."}, {"circulo": 9, "ordem": 1, "texto": "Os fluxos são descritivos. Para executar falta escolher o motor e ligar cada tarefa a um sistema."}, {"circulo": 9, "ordem": 2, "texto": "Não há tempo, volume nem carga por pessoa: nada disso foi medido, então nada foi estimado. Os únicos prazos citados são os da LGPD e da Resolução CD/ANPD nº 15/2024, com a fonte."}, {"circulo": 9, "ordem": 3, "texto": "As cadências foram validadas em 03/10/2026 (aba Parâmetros em aberto); o líder do círculo ajusta na implantação e a calibração com dados é o gate G9."}, {"circulo": 9, "ordem": 4, "texto": "As alçadas, o que a Governança decide sozinha e as regras gerais dos contratos foram aprovados em 03/10/2026 (abas Parâmetros em aberto e Propostas de parâmetros). Os rascunhos da matriz de riscos, do critério de rateio, da amostra e das regras de sigilo e guarda foram validados em 03/10/2026; o texto final é o gate G8, e o tamanho da amostra, o G9."}, {"circulo": 9, "ordem": 5, "texto": "Continuidade dos negócios (APQC 11.4.2 a 11.4.4), assessoria externa (12.4.5) e litígios (12.4.7) não têm etapa própria."}, {"circulo": 9, "ordem": 6, "texto": "Da LGPD foram conferidos os arts. 6º, 15, 16, 18, 19, 41 e 48 citados. O prazo de comunicação de incidente (três dias úteis, Resolução CD/ANPD nº 15/2024) foi lido em transcrição secundária, porque o texto oficial não abriu: conferir no Diário Oficial antes de usar."}, {"circulo": 9, "ordem": 7, "texto": "Cada empresa do Ecossistema é um controlador e indica o seu encarregado; o modelo põe o papel de encarregado na Governança, sem desenhar a indicação nem a divulgação."}, {"circulo": 9, "ordem": 8, "texto": "O desenho da amostra (estratos e tamanho) e a conferência independente dos indicadores pela amostra (GO-03, etapa 2) não têm regra escrita."}, {"circulo": 9, "ordem": 9, "texto": "O referencial de processos é o APQC PCF 7.4, de agosto de 2024."}, {"circulo": 9, "ordem": 10, "texto": "As trocas com os oito círculos já fechados foram conferidas dos dois lados pelo nome."}, {"circulo": 9, "ordem": 11, "texto": "A tarefa de quem não é do círculo (sócios, executivo, Relações) está desenhada como participação; o detalhe dela fica no círculo dono."}, {"circulo": 9, "ordem": 12, "texto": "As saídas estão listadas por etapa, não por caminho."}, {"circulo": 9, "ordem": 13, "texto": "Os números descrevem este desenho, não a operação atual."}]$j$::jsonb) as x(circulo smallint, ordem smallint, texto text);
